INSERT INTO t_p73771717_multi_page_site_proj.reviews (full_name, team_name, text, photo_url, is_published, created_at) VALUES
('Марина Соколова', 'Хореографический ансамбль «Радуга»', 'Ездили на фестиваль-конкурс «Таланты нового века» в Нягани — впечатления только положительные! Организация на высшем уровне: чёткий тайминг, никаких многочасовых ожиданий, дети выступили спокойно и без лишнего стресса. Жюри дало каждому коллективу развёрнутую обратную связь — это очень ценно для педагога. Обязательно поедем ещё раз!', '', TRUE, now() - interval '42 days'),
('Елена Кузнецова', 'Вокальная студия «Созвездие»', 'Спасибо организаторам ИНДИГО за международный конкурс «В ритме ИНДИГО» — это было настоящее творческое путешествие для наших детей. Отдельное спасибо за мастер-класс от членов жюри, ребята получили массу полезных советов по сценической подаче. Дочь привезла диплом лауреата и теперь мечтает участвовать снова.', '', TRUE, now() - interval '38 days'),
('Дмитрий Волков', 'Театральная студия «Маска»', 'Первый раз участвовали в конкурсе такого уровня — «Открытая сцена». Очень понравилось, что жюри не просто ставит баллы, а объясняет, над чем поработать. Организация поездки, гостиница и трансфер — всё было продумано до мелочей. Дети до сих пор вспоминают гала-концерт!', '', TRUE, now() - interval '35 days'),
('Ирина Смирнова', 'Ансамбль народного танца «Берёзка»', 'Уже второй год ездим на конкурсы ИНДИГО и каждый раз убеждаемся — это одна из лучших площадок для детского творчества. «Зимняя мелодия» запомнилась особенно: тёплая атмосфера, профессиональное жюри и никакой суеты. Рекомендую всем руководителям коллективов!', '', TRUE, now() - interval '30 days'),
('Ольга Петрова', 'Семейный дуэт', 'Возили дочь на фестиваль «Энергия мечты» как индивидуального участника — переживала, что без коллектива будет сложно влиться, но всё прошло прекрасно. Организаторы очень внимательные, помогли со всеми вопросами, а после выступления жюри дало тёплые слова поддержки. Спасибо ИНДИГО за такие эмоции!', '', TRUE, now() - interval '27 days'),
('Анна Морозова', 'Эстрадный коллектив «Мелодия»', 'Участвовали заочно в конкурсе «Душа России» — очень удобно, когда нет возможности выехать всей группой. Прислали видео, буквально через несколько дней пришли результаты и электронные дипломы. Качество оценивания серьёзное, чувствуется, что жюри действительно смотрит выступления, а не формально ставит оценки.', '', TRUE, now() - interval '24 days'),
('Сергей Иванов', 'Ансамбль бального танца «Гармония»', 'Отличная организация фестиваля «Истоки»! Понравилось, что для педагогов провели отдельный семинар — было полезно узнать критерии оценки из первых уст. Ребята привезли гран-при в своей возрастной категории, эмоций море. Будем участвовать и дальше.', '', TRUE, now() - interval '21 days'),
('Наталья Фёдорова', 'Вокальный коллектив «Звонкие голоса»', 'Хочу поблагодарить команду ИНДИГО за конкурс «Краски лета» — всё было организовано профессионально: от регистрации до награждения. Особенно порадовало разнообразие номинаций, каждый ребёнок смог найти свою категорию. Дипломы пришли быстро, оформление достойное.', '', TRUE, now() - interval '18 days'),
('Виктория Лебедева', 'Инструментальный ансамбль «Вдохновение»', 'Впервые попробовали онлайн-формат участия — очень удобно для ребят из небольшого города, где сложно выехать на очный конкурс. Всё чётко: загрузили видео, получили обратную связь от жюри и результаты в личном кабинете. Спасибо, что делаете конкурсы доступными для всех!', '', TRUE, now() - interval '15 days'),
('Павел Новиков', 'Театр-студия «Экспромт»', 'Ездили большой командой на конкурс-фестиваль ИНДИГО — организация продумана до деталей: расписание репетиций, комфортное ожидание, дружелюбный персонал. Жюри — действительно опытные деятели искусства, дали ценные профессиональные советы каждому коллективу. Спасибо за незабываемые впечатления!', '', TRUE, now() - interval '12 days'),
('Юлия Александрова', 'Хореографическая студия «Стиль»', 'Второй раз подряд выбираем ИНДИГО для участия наших воспитанников — и снова не разочарованы. Понравилась прозрачная система оценивания, электронные протоколы приходят сразу после конкурса. Дети получили дипломы лауреата и массу положительных эмоций от поездки.', '', TRUE, now() - interval '8 days'),
('Татьяна Гончарова', 'Школа искусств «Гамма»', 'Отправляли заявку на многожанровый конкурс ИНДИГО — участвовали сразу в двух номинациях: вокал и инструментальная музыка. Очень удобно, что можно подать сразу несколько заявок из личного кабинета. Организаторы всегда были на связи, отвечали быстро. Обязательно вернёмся в следующем сезоне!', '', TRUE, now() - interval '5 days');
